private static void Require(byte[] buf, int offset, int size)
{
    if (buf == null)
    {
        throw new ArgumentNullException(nameof(buf));
    }
    if (offset < 0 || offset > buf.Length)
    {
        throw new ArgumentOutOfRangeException(nameof(offset));
    }
    if (buf.Length - offset < size)
    {
        throw new ArgumentException("__CLASSNAME__: need " + size + " bytes, have " + (buf.Length - offset), nameof(buf));
    }
}

