// A float's bits, without BitConverter.SingleToInt32Bits (missing from
// .NET Framework) or unsafe code.
[StructLayout(LayoutKind.Explicit)]
private struct FloatBits
{
    [FieldOffset(0)] private float value;
    [FieldOffset(0)] private uint bits;

    public static uint Of(float value)
    {
        FloatBits u = new FloatBits();
        u.value = value;
        return u.bits;
    }

    public static float From(uint bits)
    {
        FloatBits u = new FloatBits();
        u.bits = bits;
        return u.value;
    }
}

