private static bool BytesEqual(byte[] a, byte[] b)
{
    for (int i = 0; i < a.Length; i++)
    {
        if (a[i] != b[i])
        {
            return false;
        }
    }
    return true;
}

private static int BytesHash(byte[] a)
{
    unchecked
    {
        int h = 1;
        foreach (byte b in a)
        {
            h = 31 * h + b;
        }
        return h;
    }
}

